Lemma fold_area_point : forall (F G : Z -> Z) l pg0 d, List.NoDup l -> In pg0 l ->
  (forall pg, In pg l -> pg <> pg0 -> F pg = G pg) -> F pg0 = G pg0 - d ->
  fold_right (fun pg acc => F pg + acc) 0 l = fold_right (fun pg acc => G pg + acc) 0 l - d.
Proof.
